/**
 * A handler for a p-code variable stored in part of a JVM {@code long}.
 * 
 * @param <ST> the JVM type of the sub variable
 * @param <SJT> the p-code type of the sub variable
 */
public interface SubInLongHandler<ST, SJT> : SubVarHandler<ST, SJT, TLong, LongJitType> where ST : BPrim<object> where SJT : SimpleJitType<ST, SJT> {

	/* @Override */
	default Emitter<Ent<N, TInt>> genLoadToBool<N>/* where N : Next */(Emitter<N> em,
			JitCodeGenerator<object> gen) {
		long mask = longMask();
		return em
				.emit(Op.lload, local().local())
				.emit(Op.ldc__l, mask)
				.emit(Op.land)
				.emit(Op.ldc__l, 0)
				.emit(Op.lcmp);
	}

	/* @Override */
	default <FT extends BPrim<object>, FJT extends SimpleJitType<FT, FJT>, N1 extends Next,
		N0 extends Ent<N1, FT>> Emitter<N1> genStoreFromStack(Emitter<N0> em,
				JitCodeGenerator<object> gen, FJT type, Ext ext, Scope scope) {
		long mask = longMask();
		return em
				.emit(Opnd.convert, type, LongJitType.I8, ext)
				.emit(Op.ldc__i, bitShift())
				.emit(Op.lshl)
